import { test, expect } from '@playwright/test';

test.describe('Export Personal Data as JSON', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/user/profile');
  });

  test('should successfully export user data as JSON file', async ({ page }) => {
    // Verify user profile page is loaded
    const profileHeader = page.getByRole('heading', { name: /user profile/i });
    await expect(profileHeader).toBeVisible();

    // Verify export button is visible and enabled
    const exportButton = page.getByRole('button', { name: /export data/i });
    await expect(exportButton).toBeVisible();
    await expect(exportButton).not.toBeDisabled();

    // Click the export button
    await exportButton.click();

    // Wait for export confirmation message
    const successMessage = page.getByText(/data exported successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify download prompt appears
    const downloadPrompt = page.getByText(/download complete/i);
    await expect(downloadPrompt).toBeVisible();

    // Verify download link is available
    const downloadLink = page.getByRole('link', { name: /download json/i });
    await expect(downloadLink).toBeVisible();

    // Click the download link
    await downloadLink.click();

    // Verify download starts
    const downloadStatus = page.getByText(/downloading/i);
    await expect(downloadStatus).toBeVisible();

    // Verify download is complete
    await expect(downloadStatus).toContainText('complete');
  });

  test('should handle export failure with error message', async ({ page }) => {
    // Intercept the export API call and simulate failure
    await page.route('**/api/user/export', route => {
      route.abort('failed');
    });

    // Verify export button is visible
    const exportButton = page.getByRole('button', { name: /export data/i });
    await expect(exportButton).toBeVisible();

    // Click the export button
    await exportButton.click();

    // Wait for error message to appear
    const errorMessage = page.getByText(/failed to export data/i);
    await expect(errorMessage).toBeVisible();

    // Verify error details are displayed
    const errorDetails = page.getByText(/server error/i);
    await expect(errorDetails).toBeVisible();

    // Verify export button is still available for retry
    await expect(exportButton).toBeVisible();

    // Verify no success message is displayed
    const successMessage = page.getByText(/data exported successfully/i);
    await expect(successMessage).not.toBeVisible();

    // Verify download link does not appear
    const downloadLink = page.getByRole('link', { name: /download json/i });
    await expect(downloadLink).not.toBeVisible();
  });
});
